        }

        .btn {
            display: inline-block;
            padding: 12px 24px;
            text-decoration: none;
            font-size: 11px;
            letter-spacing: 1px;
            text-transform: uppercase;
            border: 1px solid transparent;
            cursor: pointer;
            transition: all 0.3s ease;
            background-color: transparent;
        }

        .btn-outline {
            border-color: var(--primary-black);
            color: var(--primary-black);
        }

        .btn-outline:hover {
