        }

        @media (max-width: 768px) {
            .events-container { flex-direction: column; }
            .calendar-widget { width: 100%; }
            .team-grid { grid-template-columns: 1fr; }
            .locations-grid { grid-template-columns: 1fr; }
            .section-title { font-size: 32px; }
